// Types for the preview's choreography module (generated by tools/build_stage_js.py), loaded at run time from the
// dashboard as /static/encendido-stage.mjs (tsconfig "paths" points that name here).
export interface RobotPose { yaw: number; pitch: number; roll: number; body: number; turn: number; antL: number; antR: number; bob: number; glow: number }
export interface HumanPose { x: number; depth: number; face: number; drop: number; lean: number; look: number; tilt: number; shrug: number; sit: number;
  headDown: number; hood: number; aL: number; eL: number; aR: number; eR: number; fLx: number; fLy: number; fRx: number; fRy: number; rotL: number; rotR: number }
export interface Lights { L: number; C: number; R: number; M: number; warm: number; party: number; lamp: number }
export interface StagePose { L: RobotPose; R: RobotPose; H: HumanPose; lt: Lights }
export declare const BPM: number, BEAT: number, PH: number, N: number, DUR: number, VW: number, VH: number, FLOOR: number, TOP: number;
export declare const POS: { L: number; C: number; R: number };
export declare const PHRASES: { act: number; you: string; A: string; B: string; Y: string }[];
export declare const ACTS: { name: string; desc: string }[];
export declare function poseAt(t: number): StagePose;
export declare function setContext(ctx: CanvasRenderingContext2D): void;
export declare function drawKitchen(lt: Lights, hx: number, t: number): void;
export declare function drawRobot(cx: number, r: RobotPose): void;
export declare function drawHuman(h: HumanPose): void;
